def transform(grid):
    out=[[0]*6 for _ in range(3)]
    h,w=len(grid),len(grid[0])
    rb=[(0,4),(4,6),(6,h)]
    cb=[(0,5),(5,w)]
    for r,(a,b) in enumerate(rb):
        for c,(x,y) in enumerate(cb):
            cells=[(i,j) for i in range(a,min(b,h)) for j in range(x,min(y,w)) if grid[i][j]==2]
            if cells:
                counts={i:sum(1 for u,v in cells if u==i) for i,j in cells}
                out[r][3*c]=3 if counts[min(counts)]==1 else 1
    return out
